package com.rulecraft.decisionops.decisionapi.security;
import com.rulecraft.decisionops.decisionapi.ApiCredentialService;import com.rulecraft.decisionops.decisionapi.domain.ApiCredentialStatus;import com.rulecraft.decisionops.decisionapi.persistence.ApiCredentialRepository;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.util.List;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;
@Component public class DecisionApiKeyFilter extends OncePerRequestFilter {private final ApiCredentialRepository credentials;public DecisionApiKeyFilter(ApiCredentialRepository credentials){this.credentials=credentials;}@Override protected boolean shouldNotFilter(HttpServletRequest request){return !request.getRequestURI().startsWith("/api/runtime/v1/");}@Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{var header=request.getHeader("Authorization");if(header==null||!header.startsWith("Bearer ")||header.length()>160){unauthorized(response);return;}var secret=header.substring(7);var value=credentials.findByKeyHashAndStatus(ApiCredentialService.hash(secret),ApiCredentialStatus.ACTIVE);if(value.isEmpty()){unauthorized(response);return;}var credential=value.get();var principal=new DecisionApiPrincipal(credential.getId(),credential.getTenantId(),credential.getProjectId(),credential.getServiceId(),credential.getKeyPrefix());var authentication=UsernamePasswordAuthenticationToken.authenticated(principal,null,List.of(new SimpleGrantedAuthority("ROLE_DECISION_API")));SecurityContextHolder.getContext().setAuthentication(authentication);chain.doFilter(request,response);}private void unauthorized(HttpServletResponse response)throws IOException{SecurityContextHolder.clearContext();response.setStatus(401);response.setContentType("application/problem+json");response.getWriter().write("{\"type\":\"urn:rulecraft:problem:rc-api-key-invalid\",\"title\":\"Unauthorized\",\"status\":401,\"detail\":\"Provide an active decision API key.\",\"code\":\"RC-API-KEY-INVALID\"}");}}
